def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if all(v == 0 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 0 for r in range(h))]

    colors = {}
    for row in grid:
        for v in row:
            if v != 0:
                colors[v] = colors.get(v, 0) + 1
    background = max(colors, key=colors.get)
    marker = next(c for c in colors if c != background)

    rb = [-1] + row_seps + [h]
    cb = [-1] + col_seps + [w]
    result = []
    for i in range(len(rb) - 1):
        outrow = []
        for j in range(len(cb) - 1):
            r0, r1 = rb[i] + 1, rb[i + 1]
            c0, c1 = cb[j] + 1, cb[j + 1]
            n = sum(grid[r][c] == marker
                    for r in range(r0, r1) for c in range(c0, c1))
            outrow.append(1 if n == 2 else background)
        result.append(outrow)
    return result
